import { readFileSync } from 'node:fs';
import { execSync } from 'node:child_process';
const idx = readFileSync('libs/features/bacteria-engine/src/index.ts','utf8');
const src = {};
for (const m of idx.matchAll(/export (?:type )?\{([^}]*)\} from '([^']+)'/g)) for (const n of m[1].split(',').map(s=>s.trim().replace(/^type /,'')).filter(Boolean)) src[n]=m[2].replace('./lib/','');
const files = execSync(`grep -rlE "@wolsok/feat-shared-bacteria-engine'" apps libs tools --include=*.ts --include=*.mts --include=*.mjs`).toString().trim().split('\n');
const use = {};
for (const f of files) {
  const proj = f.startsWith('apps/bacteria-wars-functions') ? 'functions' : f.includes('bacteria-game/src/admin-kit')||f.includes('admin-kit') ? 'admin-kit' : f.includes('bacteria-wars-admin') ? 'admin' : f.includes('lazy/bacteria-game') ? 'game' : f.split('/').slice(0,3).join('/');
  const t = readFileSync(f,'utf8');
  for (const m of t.matchAll(/import (?:type )?\{([^}]*)\} from '@wolsok\/feat-shared-bacteria-engine'/g)) for (const n of m[1].split(',').map(s=>s.trim().replace(/^type /,'').split(' as ')[0]).filter(Boolean)) { (use[n] ??= new Set()).add(proj + (/\.(spec|emulator)\.ts$/.test(f)||f.includes('/testing/')?'(test)':'')); }
}
const byFile = {};
for (const [n,f] of Object.entries(src)) (byFile[f] ??= []).push(n + ' [' + [...(use[n]??[])].join(',') + ']');
for (const [f,ns] of Object.entries(byFile)) console.log(f + '\n   ' + ns.join('\n   '));
EOF
node $SP/usage.mjs > $SP/usage.txt; wc -l $SP/usage.txt; ls libs/features/lazy/bacteria-game/src; grep -n "admin-kit" tsconfig.base.json

